import paramiko
c = paramiko.SSHClient()
c.set_missing_host_key_policy(paramiko.AutoAddPolicy())
c.connect('46.202.154.25', 22, 'root', '2N00py123+++')

# More aggressive debug - catch async errors too
debug_html = b'''<!doctype html>
<html>
<head>
<meta charset="utf-8"/>
<title>Arelorian</title>
<style>
body{background:#000;color:#0f0;font-family:monospace;margin:0;height:100vh}
#d{position:fixed;top:0;left:0;right:0;bottom:0;overflow:auto;padding:20px;z-index:999999}
#l{color:#888}
</style>
<script>
var dbg=document.createElement('div');
dbg.id='d';
dbg.innerHTML='<div id="l">Starting...</div>';
document.body.insertBefore(dbg,document.body.firstChild);

window.onerror=function(m,u,l,c,e){
  var err='ERR: '+m+' Line:'+l;
  if(e&&e.stack)err+='\\n'+e.stack;
  document.getElementById('l').innerText=err;
  document.body.style.background='#300';
  return true;
};

window.addEventListener('unhandledrejection',function(e){
  document.getElementById('l').innerText='UNHANDLED: '+e.reason;
  document.body.style.background='#300';
});

var oldLog=console.log;
console.log=function(){
  oldLog.apply(console,arguments);
  var d=document.getElementById('l');
  d.innerText=Array.from(arguments).join(' ');
};

console.log('JS loading...');
</script>
</head>
<body>
<canvas id="application-canvas" style="position:fixed;inset:0"></canvas>
<script type="module" src="/assets/main-CLZYnZ3S.js" onload="console.log('MAIN LOADED')" onerror="console.log('MAIN ERROR: '+arguments[0])"><\/script>
</body>
</html>'''

sftp = c.open_sftp()
with sftp.file('/tmp/debug.html', 'wb') as f:
    f.write(debug_html)

c.exec_command('cp /tmp/debug.html /opt/areloria/client/dist/index.html')
print('Debug v2 deployed')

c.close()
EOF

